#import "DGCommon.h"
#import "DGVerification.h"
@interface DGMusicPage:NSObject<WKNavigationDelegate>
@property(nonatomic,strong) WKWebView *web;
@property(nonatomic,weak) DGBridge *bridge;
@property(nonatomic,strong) UIView *container;
@property(nonatomic,copy) NSString *identifier;
@property(nonatomic,copy) DGResult pending;
@property(nonatomic,strong) NSDate *deadline;
@property(nonatomic) NSInteger offset;
@property(nonatomic) BOOL legacyTried;
- (void)read:(NSString *)cursor completion:(DGResult)completion;
@end
static NSMutableDictionary<NSString *,DGMusicPage *> *DGMusicPages(void){static NSMutableDictionary *pages;static dispatch_once_t once;dispatch_once(&once,^{pages=[NSMutableDictionary dictionary];});return pages;}
@implementation DGMusicPage
- (instancetype)init{if((self=[super init])){WKWebViewConfiguration *config=[WKWebViewConfiguration new];DGSessionConfigure(config);config.allowsInlineMediaPlayback=YES;config.mediaTypesRequiringUserActionForPlayback=WKAudiovisualMediaTypeAll;NSString *script=[NSString stringWithContentsOfFile:[NSBundle.mainBundle pathForResource:@"music-page" ofType:@"js"] encoding:NSUTF8StringEncoding error:nil]?:@"";[config.userContentController addUserScript:[[WKUserScript alloc]initWithSource:script injectionTime:WKUserScriptInjectionTimeAtDocumentStart forMainFrameOnly:YES]];NSString *adapter=[NSString stringWithContentsOfFile:[NSBundle.mainBundle pathForResource:@"bridge" ofType:@"js"] encoding:NSUTF8StringEncoding error:nil]?:@"";[config.userContentController addUserScript:[[WKUserScript alloc]initWithSource:adapter injectionTime:WKUserScriptInjectionTimeAtDocumentEnd forMainFrameOnly:YES]];_web=[[WKWebView alloc]initWithFrame:CGRectMake(0,0,1280,900) configuration:config];_web.customUserAgent=DGUserAgent();_web.navigationDelegate=self;_web.userInteractionEnabled=NO;[_web setAllMediaPlaybackSuspended:YES completionHandler:nil];_container=[[UIView alloc]initWithFrame:CGRectMake(0,0,1,1)];_container.alpha=.01;_container.clipsToBounds=YES;_container.userInteractionEnabled=NO;[_container addSubview:_web];}return self;}
- (void)read:(NSString *)cursor completion:(DGResult)completion{if(self.pending){completion(nil,@"原声作品正在加载，请稍候");return;}self.pending=completion;self.offset=[cursor hasPrefix:@"web:"]?[[cursor substringFromIndex:4]integerValue]:0;self.deadline=[NSDate dateWithTimeIntervalSinceNow:16];if(!_web.URL){DGSessionPrepare(_web,YES,^{[self->_web loadRequest:[NSURLRequest requestWithURL:[NSURL URLWithString:[@"https://www.douyin.com/music/" stringByAppendingString:self.identifier]]]];[self poll];});}else{if(self.offset)[_web evaluateJavaScript:@"window.scrollBy(0,innerHeight*1.2);document.querySelectorAll('div').forEach(e=>{if(e.clientHeight>250&&e.scrollHeight>e.clientHeight+500)e.scrollTop+=e.clientHeight*.8})" completionHandler:nil];[self poll];}}
- (void)poll{if(!self.pending)return;__weak DGMusicPage *weak=self;[_web callAsyncJavaScript:@"if(!window.DGMusicPage||!window.DouGlass)return {items:[]};if(location.hostname==='www.iesdouyin.com'&&!window.__dgLegacyRead){window.__dgLegacyRead=true;window.DouGlass.request('legacyMusic',{id:identifier,cursor:'0'}).catch(()=>{});}return window.DGMusicPage.read(identifier,offset);" arguments:@{@"identifier":self.identifier,@"offset":@(self.offset)} inFrame:nil inContentWorld:WKContentWorld.pageWorld completionHandler:^(id value,NSError *error){DGMusicPage *self=weak;if(!self||!self.pending)return;NSDictionary *result=[value isKindOfClass:NSDictionary.class]?value:nil;if([result[@"verification"]boolValue])DGOpenVerificationPage(self.bridge,self.web,@"musicWorks",@{@"id":self.identifier});NSArray *items=DGNormalizeWebItems(result[@"items"]);if(items.count){NSMutableDictionary *native=[result mutableCopy];native[@"items"]=items;DGResult done=self.pending;self.pending=nil;done(native,nil);return;}if(!self.legacyTried&&self.deadline.timeIntervalSinceNow<8){self.legacyTried=YES;[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.location.href='https://www.iesdouyin.com/share/music/%@/'",self.identifier] completionHandler:nil];self.deadline=[NSDate dateWithTimeIntervalSinceNow:18];}if([NSDate.date compare:self.deadline]!=NSOrderedAscending){DGResult done=self.pending;self.pending=nil;if(self.offset)done(@{@"items":@[],@"more":@NO,@"cursor":[NSString stringWithFormat:@"web:%ld",(long)self.offset]},nil);else done(nil,@"平台原声服务暂不可用，可使用上方网页入口手动加载，已有内容会保留");return;}dispatch_after(dispatch_time(DISPATCH_TIME_NOW,800*NSEC_PER_MSEC),dispatch_get_main_queue(),^{[self poll];});}];}
- (void)webView:(WKWebView *)web decidePolicyForNavigationAction:(WKNavigationAction *)action decisionHandler:(void (^)(WKNavigationActionPolicy))decision{decision([@[@"http",@"https",@"about",@"blob",@"data"]containsObject:action.request.URL.scheme.lowercaseString]?WKNavigationActionPolicyAllow:WKNavigationActionPolicyCancel);}
@end
void DGReadMusicPage(DGBridge *bridge,NSString *identifier,NSString *cursor,DGResult completion){
 if(!identifier.length||[identifier rangeOfCharacterFromSet:NSCharacterSet.decimalDigitCharacterSet.invertedSet].location!=NSNotFound){completion(nil,@"平台未提供有效原声标识");return;}
 NSMutableDictionary<NSString *,DGMusicPage *> *pages=DGMusicPages();
 DGMusicPage *page=pages[identifier];if(!page){if(pages.count>=2)for(NSString *key in pages.allKeys){if(!pages[key].pending){[pages[key].container removeFromSuperview];[pages removeObjectForKey:key];break;}}page=[DGMusicPage new];page.identifier=identifier;pages[identifier]=page;}page.bridge=bridge;UIView *host=bridge.web.superview.superview?:bridge.web.superview;if(page.container.superview!=host)[host addSubview:page.container];[page read:cursor?:@"0" completion:completion];
}
void DGResetMusicPages(void){for(DGMusicPage *page in DGMusicPages().allValues){[page.web stopLoading];[page.container removeFromSuperview];if(page.pending){DGResult done=page.pending;page.pending=nil;done(nil,@"账号已变化，请重新打开原声页");}}[DGMusicPages()removeAllObjects];}

